w('pw_gf',{"airline":"Gulf Air","power":{"checked":"22 November 2026","answer":"Gulf Air allows each passenger a maximum of two lithium-ion power banks, each up to 100 Wh, with protected terminals. They may not be recharged from the in-flight supply, may not power other devices, and may not be stored in overhead lockers.","sections":[{"h":"🔋 What Gulf Air says about power banks","p":"From the Gulf Air Conditions of Carriage, article 8.3.8 \"Power banks\", read on 22 November 2026.","table":{"head":["Question","Gulf Air rule"],"rows":[["How many","A maximum of two lithium-ion power banks per passenger"],["Capacity","Each not exceeding 100 Wh"],["Terminals","Protected against damage and short circuits"],["Recharging the power bank","Not allowed from the in-flight power supply"],["Powering other devices","A power bank must not be used to charge or supply other devices; you may use the in-flight charging points to power your own devices directly"],["Where","Not in overhead lockers; keep it readily accessible, for example in the seat pocket or on your person"],["Before boarding","Make sure your devices are charged; Gulf Air does not provide charging to replace this"]]},"list":["<strong>Not on the page:</strong> this article does not say whether power banks may go in checked baggage; ask Gulf Air."]}],"faq":[["How many power banks can I take on Gulf Air?","A maximum of two lithium-ion power banks per passenger, each up to 100 Wh."],["Where must I keep my power bank on Gulf Air?","In the seat pocket or on your person, not in the overhead locker, so it can be reached quickly in an emergency."],["Can I charge my phone from a power bank on Gulf Air?","No. A power bank must not be used to charge other devices during the flight; use the in-flight charging points for your devices instead."]],"sources":[["https://www.gulfair.com/transparency/conditions-of-carriage","Gulf Air &mdash; Conditions of Carriage"]]}})
w('pw_saa',{"airline":"South African Airways","power":{"checked":"22 November 2026","answer":"South African Airways allows power banks of up to 100 Wh in carry-on baggage only, individually packed against short circuits. They may not be charged from in-seat power or used to power devices during taxi, take-off or landing, and must be stored under the seat, not in overhead bins.","sections":[{"h":"🔋 What South African Airways says about power banks","p":"From the South African Airways page \"Restricted Baggage Items and Dangerous Goods\", sections Power Banks and Lithium Batteries, read on 22 November 2026.","table":{"head":["Question","South African Airways rule"],"rows":[["Where","Carry-on baggage only; never in checked baggage, and security may remove them"],["Capacity","Maximum 100 Wh (the page names 27,000 mAh as an example guide)"],["Packing","Individually packed to prevent short circuits: original packaging, insulated terminals, or a protective pouch or bag"],["During the flight","Do not charge power banks from in-seat or inflight power; do not use them to power other devices during taxi, take-off or landing"],["Storage","Under the seat in front or another designated place, not in overhead bins"],["Not accepted","Damaged, defective or recalled units; overheating, swollen or leaking units; any unit with smoke, burning smell or expansion"],["Spare lithium batteries","Carry-on only; up to two spare lithium-ion batteries of 100 to 160 Wh; 20 spare batteries in total, each protected"],["mAh to Wh","Wh = mAh x volts / 1000; the page's example: 10,000 mAh at 12 V is 120 Wh"]]},"list":["<strong>Not on the page:</strong> the page does not say whether power banks of 100 to 160 Wh are accepted; it names 100 Wh as the airline limit."]}],"faq":[["Can I put a power bank in my checked bag on South African Airways?","No. Power banks must stay in carry-on baggage and may be removed by security if packed in checked luggage."],["What size power bank can I take on South African Airways?","Up to 100 Wh; the page also gives 27,000 mAh as a guide."],["Can I charge my power bank on a South African Airways flight?","No. Do not charge spare batteries or power banks from in-seat or inflight power."]],"sources":[["https://www.flysaa.com/manage-fly/baggage/restricted-items","South African Airways &mdash; Restricted Baggage Items and Dangerous Goods"]]}})
